DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260508170641_InitialPostgres') THEN
    CREATE TABLE "Products" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(200) NOT NULL,
        "SKU" character varying(50) NOT NULL,
        "CategoryId" integer NOT NULL,
        "SupplierId" integer NOT NULL,
        "BaseUnitId" integer NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Products" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Products_Categories_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "Categories" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Products_Suppliers_SupplierId" FOREIGN KEY ("SupplierId") REFERENCES "Suppliers" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Products_Units_BaseUnitId" FOREIGN KEY ("BaseUnitId") REFERENCES "Units" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
