        "ConversionFactor" numeric NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "UpdatedAt" timestamp with time zone,
        CONSTRAINT "PK_UnitConversions" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_UnitConversions_Products_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Products" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_UnitConversions_Units_FromUnitId" FOREIGN KEY ("FromUnitId") REFERENCES "Units" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_UnitConversions_Units_ToUnitId" FOREIGN KEY ("ToUnitId") REFERENCES "Units" ("Id") ON DELETE RESTRICT
